135	    setActiveTab,
136	    setDate,
137	    setSearchTerm,
138	    setIsAddModalOpen,
139	    setIsImportModalOpen,
140	    handleSubmit,
141	    setHistoryFilter,
142	    setAnalyticsPreset,
143	    setAnalyticsViewMode,
144	    setIsManageModalOpen,
145	    productionEntries,
146	  ]);
147	
148	  useMiaActions('/producao-diaria', handlers);
149	}
