1280	      // 5. Análise por Produto (Capilaridade)
1281	      const productMap: Record<string, { total: number; quantities: number[]; dates: string[] }> = {};
1282	
1283	      currentEntries.forEach(e => {
1284	        if (!productMap[e.product_name]) {
