1292	      const products: ProductStats[] = Object.entries(productMap).map(([name, stats]) => {
1293	        const uniqueDates = new Set(stats.dates).size;
1294	        const avgDaily = stats.total / (uniqueDates || 1);
1295	        const maxDaily = Math.max(...stats.quantities);
1296	
1297	        // Volatilidade (Desvio Padrão)
1298	        const mean = stats.total / stats.quantities.length;
1299	        const variance = stats.quantities.reduce((sum, q) => sum + Math.pow(q - mean, 2), 0) / stats.quantities.length;
1300	        const volatility = Math.sqrt(variance);
1301	
1302	        return {
1303	          name,
1304	          total: stats.total,
1305	          avgDaily,
1306	          maxDaily,
1307	          frequency: (uniqueDates / daysDiff) * 100, // % dos dias do período
1308	          volatility,
1309	          share: (stats.total / (totalProduction || 1)) * 100,
1310	          dates: stats.dates.sort()
1311	        };
1312	      }).sort((a, b) => b.total - a.total);
