1318	      const dailyMap: Record<number, { date: string; total: number; prevTotal: number }> = {};
1319	
1320	      for (let i = 0; i < daysDiff; i++) {
1321	        // Data atual
1322	        const dCurrent = new Date(currentStart);
1323	        dCurrent.setDate(dCurrent.getDate() + i);
1324	        const sCurrent = formatDateISO(dCurrent);
