1330	
1331	        const currentDayTotal = currentEntries.filter(e => e.date === sCurrent).reduce((s, e) => s + e.quantity, 0);
1332	        const prevDayTotal = previousEntries.filter(e => e.date === sPrev).reduce((s, e) => s + e.quantity, 0);
1333	
1334	        dailyMap[i] = {
1335	          date: sCurrent,
1336	          total: currentDayTotal,
1337	          prevTotal: prevDayTotal
1338	        };
1339	      }
1340	
1341	      const dailyTrend = Object.values(dailyMap).sort((a, b) => a.date.localeCompare(b.date)).map(d => ({
1342	        date: d.date,
1343	        total: d.total,
1344	        previousTotal: d.prevTotal
1345	      }));
1346	
1347	      // 7. Distribuição Horária (Heatmap/Horários de Pico)
1348	      // Usar created_at para extrair hora. Se created_at for nulo, ignorar.
1349	      const hoursMap: Record<number, number> = {};
