1370	      const monthlyTrend = Object.entries(monthlyMap)
1371	        .map(([month, total]) => ({ month, total }))
1372	        .sort((a, b) => a.month.localeCompare(b.month));
1373	
1374	      const hourlyDistribution = Object.entries(hoursMap).map(([h, count]) => ({
1375	        hour: parseInt(h),
