1	-- Combined migration to fix 'perdas' table schema
2	-- 1. Adds 'foto_url' and 'foto_storage_path' if missing
3	-- 2. Adds 'loja_id' if missing
4	-- 3. Fixes Foreign Key for 'loja_id'
5	
6	DO $$
7	BEGIN
8	    -- 1. Add columns if they don't exist
9	    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'perdas' AND column_name = 'foto_url') THEN
10	        ALTER TABLE public.perdas ADD COLUMN foto_url TEXT;
11	    END IF;
12	
13	    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'perdas' AND column_name = 'foto_storage_path') THEN
14	        ALTER TABLE public.perdas ADD COLUMN foto_storage_path TEXT;
15	    END IF;
16	
17	    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'perdas' AND column_name = 'loja_id') THEN
18	        ALTER TABLE public.perdas ADD COLUMN loja_id INTEGER;
19	    END IF;
20	
21	    -- 2. Drop existing constraint to ensure clean state
22	    IF EXISTS (SELECT 1 FROM information_schema.table_constraints WHERE table_name = 'perdas' AND constraint_type = 'FOREIGN KEY' AND constraint_name = 'perdas_loja_id_fkey') THEN
23	        ALTER TABLE public.perdas DROP CONSTRAINT perdas_loja_id_fkey;
24	    END IF;
25	END $$;
26	
27	-- 3. Re-add Foreign Key constraint
28	ALTER TABLE public.perdas
29	  ADD CONSTRAINT perdas_loja_id_fkey
30	  FOREIGN KEY (loja_id)
31	  REFERENCES public.lojas(id)
32	  ON DELETE SET NULL;
33	
34	-- 4. Create index for performance
35	CREATE INDEX IF NOT EXISTS idx_perdas_loja_id ON public.perdas(loja_id);
36	
37	-- 5. Force schema cache reload
38	NOTIFY pgrst, 'reload config';
