107	function AbcHeatbar({ items }: { items: AbcItem[] }) {
108	  if (items.length === 0) return null;
109	
110	  const maxFat = items[0]?.faturamento || 1;
111	
112	  return (
113	    <div className="space-y-1.5">
114	      <div className="flex items-center justify-between text-[10px] text-muted-foreground">
115	        <span>Curva ABC — produtos por volume vendido (60 dias)</span>
116	        <div className="flex items-center gap-3">
117	          <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-sm bg-emerald-500" /> A (80%)</span>
118	          <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-sm bg-amber-400" /> B (15%)</span>
119	          <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-sm bg-gray-300" /> C (5%)</span>
120	        </div>
121	      </div>
122	      <div className="flex gap-[1px] h-6 rounded-lg overflow-hidden">
123	        {items.map(item => {
124	          const width = Math.max((item.faturamento / maxFat) * 100, 1.5);
125	          const color = item.curva === 'A'
126	            ? 'bg-emerald-500 hover:bg-emerald-400'
127	            : item.curva === 'B'
128	              ? 'bg-amber-400 hover:bg-amber-300'
129	              : 'bg-gray-300 hover:bg-gray-200 dark:bg-gray-600';
130	
131	          return (
132	            <Tooltip key={item.produto_master_id}>
133	              <TooltipTrigger asChild>
134	                <div
135	                  className={cn('h-full transition-colors cursor-default', color)}
136	                  style={{ width: `${width}%`, minWidth: '2px' }}
137	                />
138	              </TooltipTrigger>
139	              <TooltipContent side="bottom" className="text-xs">
140	                <p className="font-semibold">{item.nome}</p>
141	                <p>{item.faturamento.toLocaleString('pt-BR')} un · {item.pct}% do volume · Curva {item.curva}</p>
142	              </TooltipContent>
143	            </Tooltip>
144	          );
145	        })}
146	      </div>
147	    </div>
148	  );
149	}
